function planAcknowledgement({ body, secret, from }) {
  if (typeof secret !== "string" || secret.length < 24 || secret === "YOUR_ACTION_SECRET")
    throw Error("Configure a strong action secret");
  const received = body?.context?.action_secret;
  if (typeof received !== "string" || received !== secret) throw Error("Invalid action secret");
  const incident = body?.context?.pagerduty_incident,
    channel = body?.channel_id;
  if (
    typeof incident !== "string" ||
    !incident.trim() ||
    typeof channel !== "string" ||
    !channel.trim()
  )
    throw Error("Missing incident or channel");
  if (typeof from !== "string" || !/^\S+@\S+\.\S+$/.test(from) || from === "YOUR_PAGERDUTY_EMAIL")
    throw Error("Configure PagerDuty user email");
  return { incidentId: incident, channelId: channel, from };
}

return {
  json: planAcknowledgement({
    body: $json.body,
    secret: $env.MATTERMOST_ACTION_SECRET,
    from: "YOUR_PAGERDUTY_EMAIL",
  }),
};

function confirmAcknowledgement({ incident, incidentId }) {
  if (!incident || incident.id !== incidentId || incident.status !== "acknowledged")
    throw Error("PagerDuty did not confirm acknowledgement");
  return { message: "💪🏼 Incident status has been changed to Acknowledged on PagerDuty." };
}

return {
  json: confirmAcknowledgement({
    incident: $json,
    incidentId: $("Validate the action").first().json.incidentId,
  }),
};
